package me.eiakoji.wiki.eip.channels;

import java.time.Duration;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class VerifyChannels {

    public sealed interface MessagePayload permits OrderPlacedEvent, PaymentReceivedEvent, CorruptedPayload {}

    public record OrderPlacedEvent(String orderId, double amount, Instant timestamp) implements MessagePayload {}
    public record PaymentReceivedEvent(String paymentId, String orderId, double amount) implements MessagePayload {}
    public record CorruptedPayload(String rawBytes, String parseError) implements MessagePayload {}

    public record Envelope<T extends MessagePayload>(
        UUID messageId,
        T payload,
        Map<String, String> headers,
        Instant publishedAt,
        AtomicInteger retryCount
    ) {
        public static <T extends MessagePayload> Envelope<T> of(T payload) {
            return new Envelope<>(UUID.randomUUID(), payload, new ConcurrentHashMap<>(), Instant.now(), new AtomicInteger(0));
        }
    }

    public static class DurabilityBarrier {
        private final List<String> writeAheadLog = Collections.synchronizedList(new ArrayList<>());

        public synchronized boolean persistWithFsync(Envelope<?> envelope) {
            String entry = envelope.messageId() + ":" + envelope.payload().toString();
            writeAheadLog.add(entry);
            return true;
        }

        public int logDepth() {
            return writeAheadLog.size();
        }
    }

    public static class PointToPointQueue<T extends MessagePayload> {
        private final BlockingQueue<Envelope<T>> queue;
        private final DurabilityBarrier durability;

        public PointToPointQueue(int capacity, DurabilityBarrier durability) {
            this.queue = new ArrayBlockingQueue<>(capacity);
            this.durability = durability;
        }

        public boolean send(Envelope<T> message) {
            durability.persistWithFsync(message);
            return queue.offer(message);
        }

        public Optional<Envelope<T>> poll(Duration timeout) throws InterruptedException {
            return Optional.ofNullable(queue.poll(timeout.toMillis(), TimeUnit.MILLISECONDS));
        }

        public int depth() {
            return queue.size();
        }
    }

    public static class PublishSubscribeTopic<T extends MessagePayload> {
        private final List<BlockingQueue<Envelope<T>>> subscriberQueues = new CopyOnWriteArrayList<>();
        private final DurabilityBarrier durability;

        public PublishSubscribeTopic(DurabilityBarrier durability) {
            this.durability = durability;
        }

        public BlockingQueue<Envelope<T>> registerSubscriber(int bufferCapacity) {
            BlockingQueue<Envelope<T>> subQueue = new ArrayBlockingQueue<>(bufferCapacity);
            subscriberQueues.add(subQueue);
            return subQueue;
        }

        public void publish(Envelope<T> message) {
            durability.persistWithFsync(message);
            for (BlockingQueue<Envelope<T>> queue : subscriberQueues) {
                queue.offer(message);
            }
        }
    }

    public static class ChannelTriageCoordinator {
        private final PointToPointQueue<MessagePayload> invalidMessageChannel;
        private final PointToPointQueue<MessagePayload> deadLetterChannel;
        private final int maxRetries;

        public ChannelTriageCoordinator(
            PointToPointQueue<MessagePayload> invalidMessageChannel,
            PointToPointQueue<MessagePayload> deadLetterChannel,
            int maxRetries
        ) {
            this.invalidMessageChannel = invalidMessageChannel;
            this.deadLetterChannel = deadLetterChannel;
            this.maxRetries = maxRetries;
        }

        public enum TriageResult { PROCESSED, INVALID_QUARANTINED, RETRIED, DLQ_EXHAUSTED }

        public TriageResult handleMessage(Envelope<MessagePayload> message, ConsumerLogic logic) {
            if (message.payload() instanceof CorruptedPayload) {
                message.headers().put("X-Quarantine-Reason", "SYNTACTIC_VALIDATION_FAILURE");
                invalidMessageChannel.send(message);
                return TriageResult.INVALID_QUARANTINED;
            }

            try {
                logic.execute(message);
                return TriageResult.PROCESSED;
            } catch (Exception ex) {
                int retries = message.retryCount().incrementAndGet();
                if (retries >= maxRetries) {
                    message.headers().put("X-DLQ-Reason", "RETRY_BUDGET_EXHAUSTED:" + ex.getMessage());
                    message.headers().put("X-Retry-Attempts", String.valueOf(retries));
                    deadLetterChannel.send(message);
                    return TriageResult.DLQ_EXHAUSTED;
                } else {
                    return TriageResult.RETRIED;
                }
            }
        }
    }

    @FunctionalInterface
    public interface ConsumerLogic {
        void execute(Envelope<MessagePayload> envelope) throws Exception;
    }
}
